package com.lexorion.payroll.tenant;import java.util.*;import org.springframework.stereotype.Component;@Component public class TrustedPayrollContextHolder{private final ThreadLocal<TrustedPayrollContext> value=new ThreadLocal<>();public void set(TrustedPayrollContext v){value.set(v);}public TrustedPayrollContext require(){return Optional.ofNullable(value.get()).orElseThrow(()->new IllegalStateException("Trusted Payroll context required"));}public void clear(){value.remove();}}
